{
  "devices": [
    {
      "device": "bio_shake",
      "existing_tags": [
        {
          "id": "4312",
          "name": "备料&前处理设备",
          "name_en": "Material Preparation & Pre-processing Equipment",
          "type": "experimental_step",
          "rationale": "该设备常用于微孔板样品孵育、溶解与混匀前处理，符合样品前处理环节。"
        },
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "可在控温和振荡条件下直接执行板上反应混合与孵育流程。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "type": "experimental_domain",
          "rationale": "描述明确指出用于分子生物学与生化实验，属于生命科学领域。"
        },
        {
          "id": "4319",
          "name": "溶液配制与反应",
          "name_en": "Solution Preparation & Reaction",
          "type": "experimental_domain",
          "rationale": "微孔板内样品的溶解、混匀和孵育本质上是溶液体系处理与反应准备。"
        },
        {
          "id": "4327",
          "name": "基因编辑、分子生物学与育种",
          "name_en": "Gene Editing, Molecular Biology & Breeding",
          "type": "experimental_scene",
          "rationale": "设备典型用途即分子生物学流程中的板上孵育与混匀。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "type": "experimental_scene",
          "rationale": "微孔板恒温振荡在细胞相关样品培养与处理场景中常见。"
        },
        {
          "id": "4389",
          "name": "恒温摇床",
          "name_en": "Constant Temperature Shaker",
          "type": "device_template_tag",
          "rationale": "核心能力是恒温+振荡混匀，与恒温摇床功能高度一致。"
        },
        {
          "id": "4421",
          "name": "热混匀仪",
          "name_en": "Thermomixer",
          "type": "device_template_tag",
          "rationale": "设备执行加热并同步振荡混匀，和热混匀仪使用模式一致。"
        }
      ],
      "proposed_new_tags": []
    },
    {
      "device": "cc_core",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "CC负责启动/停止序列并执行实时时序控制，直接属于实验执行环节核心控制。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0001",
          "name": "量子信息与精密测控",
          "name_en": "Quantum Information & Precision Measurement Control",
          "type": "experimental_domain",
          "rationale": "设备用于量子实验实时控制与同步，现有领域标签缺少量子测控方向。"
        },
        {
          "id": "P-0002",
          "name": "超导量子比特实验",
          "name_en": "Superconducting Qubit Experiments",
          "type": "experimental_scene",
          "rationale": "描述明确指出常用于超导量子比特实验室的时序与序列控制。"
        },
        {
          "id": "P-0003",
          "name": "中央时序序列控制器",
          "name_en": "Central Timing and Sequence Controller",
          "type": "device_template_tag",
          "rationale": "该设备本质是多模块协调的中央时序/序列控制仪，现有模板无对应项。"
        }
      ]
    },
    {
      "device": "cryo_tel_gt",
      "existing_tags": [
        {
          "id": "4316",
          "name": "表征设备",
          "name_en": "Characterization Equipment",
          "type": "experimental_step",
          "rationale": "设备用于低温测试环境构建与温控，常服务于样品低温表征测试。"
        },
        {
          "id": "4312",
          "name": "备料&前处理设备",
          "name_en": "Material Preparation & Pre-processing Equipment",
          "type": "experimental_step",
          "rationale": "可用于样品测试前冷却与温度稳定化，属于实验前处理支持设备。"
        },
        {
          "id": "4325",
          "name": "智慧表征与检测中心",
          "name_en": "Intelligent Characterization & Testing Center",
          "type": "experimental_domain",
          "rationale": "其核心价值在于为检测/测试提供可控低温条件，契合表征检测基础设施。"
        },
        {
          "id": "4357",
          "name": "物化表征测试中心",
          "name_en": "Physicochemical Characterization & Testing Center",
          "type": "experimental_scene",
          "rationale": "低温稳定控制常用于物化参数测试与性能评估场景。"
        },
        {
          "id": "4369",
          "name": "冷热水机",
          "name_en": "Chiller / Heater Unit",
          "type": "device_template_tag",
          "rationale": "虽为更低温级别设备，但其功能同属实验热管理/冷却温控类。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0004",
          "name": "低温制冷机",
          "name_en": "Cryocooler",
          "type": "device_template_tag",
          "rationale": "该设备支持温度/功率闭环、PID参数与低温设定，需独立于普通冷热水机的模板标签。"
        }
      ]
    },
    {
      "device": "cvd_control",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "该控制系统直接负责配方下发、运行与监控，属于CVD工艺执行核心。"
        },
        {
          "id": "4322",
          "name": "表面/薄膜体系",
          "name_en": "Surface / Thin Film System",
          "type": "experimental_domain",
          "rationale": "设备明确用于CVD薄膜生长过程控制，典型薄膜体系实验域。"
        },
        {
          "id": "4344",
          "name": "涂层材料",
          "name_en": "Coating Materials",
          "type": "experimental_scene",
          "rationale": "CVD常用于沉积功能涂层，且描述强调薄膜沉积工艺流程。"
        },
        {
          "id": "4373",
          "name": "化学气相沉积设备",
          "name_en": "Chemical Vapor Deposition System",
          "type": "device_template_tag",
          "rationale": "该系统就是化学气相沉积装置的工艺控制界面与运行控制核心。"
        }
      ],
      "proposed_new_tags": []
    },
    {
      "device": "cytomat_backend",
      "existing_tags": [
        {
          "id": "4315",
          "name": "器件/细胞设备",
          "name_en": "Device / Cell Equipment",
          "type": "experimental_step",
          "rationale": "设备用于细胞相关微孔板培养与环境维持，属于细胞实验关键设备。"
        },
        {
          "id": "4317",
          "name": "物流/机械",
          "name_en": "Logistics / Machinery",
          "type": "experimental_step",
          "rationale": "具备板件在存储、等待、转运、外部位之间的自动机械传送能力。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "type": "experimental_domain",
          "rationale": "受控温湿度与CO2/O2培养环境对应生命科学自动化培养场景。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "type": "experimental_scene",
          "rationale": "自动化微孔板培养与存储直接服务细胞实验流程。"
        },
        {
          "id": "4442",
          "name": "组织培养试验箱",
          "name_en": "Tissue Culture Chamber",
          "type": "device_template_tag",
          "rationale": "具备温度、气体与湿度受控培养功能，与培养箱类设备高度相关。"
        },
        {
          "id": "4446",
          "name": "自动化耗材堆栈",
          "name_en": "Automated Consumable Stack",
          "type": "device_template_tag",
          "rationale": "具备微孔板存储位管理与自动取放转运，符合自动化堆栈/仓储特征。"
        },
        {
          "id": "4389",
          "name": "恒温摇床",
          "name_en": "Constant Temperature Shaker",
          "type": "device_template_tag",
          "rationale": "设备支持振荡培养功能，和恒温振荡培养用途相符。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0005",
          "name": "自动化微孔板培养存储系统",
          "name_en": "Automated Microplate Incubator-Storage System",
          "type": "device_template_tag",
          "rationale": "现有模板难完整覆盖其培养+存储+转运+条码追踪一体化特征，需专门模板。"
        }
      ]
    }
  ]
}

